CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE companies (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, code TEXT, cui TEXT, regcom TEXT, country TEXT DEFAULT 'RO', currency TEXT DEFAULT 'RON',
  address TEXT, iban TEXT, bank TEXT, logo TEXT, header TEXT, footer TEXT, settings TEXT DEFAULT '{}', active INTEGER DEFAULT 1
);
CREATE TABLE points (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL REFERENCES companies(id), name TEXT NOT NULL, types TEXT DEFAULT '[]',
  country TEXT DEFAULT 'RO', county TEXT, city TEXT, address TEXT, postal TEXT,
  env_nr TEXT, env_issuer TEXT, env_from TEXT, env_to TEXT, series TEXT DEFAULT '{}', active INTEGER DEFAULT 1
);
CREATE TABLE series (point_id INTEGER NOT NULL, prefix TEXT NOT NULL, year INTEGER NOT NULL, next INTEGER NOT NULL, PRIMARY KEY (point_id, prefix, year));
CREATE TABLE rates (
  id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL, country TEXT NOT NULL, kind TEXT NOT NULL, rate REAL NOT NULL,
  valid_from TEXT NOT NULL, valid_to TEXT
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT, pass_hash TEXT, pass_salt TEXT, lang TEXT DEFAULT 'ro', active INTEGER DEFAULT 1, created TEXT
);
CREATE TABLE user_roles (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, company_id INTEGER, point_id INTEGER, role TEXT NOT NULL);
CREATE TABLE audit (
  id INTEGER PRIMARY KEY, ts TEXT NOT NULL, user_id INTEGER, user_name TEXT, entity TEXT NOT NULL, entity_id TEXT, action TEXT NOT NULL,
  reason TEXT, before TEXT, after TEXT, error INTEGER DEFAULT 0
);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT, 'Jurnalul de audit nu se poate modifica.'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT, 'Jurnalul de audit nu se poate șterge.'); END;
CREATE TABLE partners (
  id INTEGER PRIMARY KEY, type TEXT NOT NULL, roles TEXT DEFAULT '[]', name TEXT NOT NULL,
  first_name TEXT, last_name TEXT, cnp TEXT, id_series TEXT, id_number TEXT, id_issuer TEXT, id_issued TEXT, id_expiry TEXT,
  cui TEXT, regcom TEXT, country TEXT DEFAULT 'RO', county TEXT, city TEXT, address TEXT, postal TEXT,
  phone TEXT, email TEXT, iban TEXT, bank TEXT, account_holder TEXT, contacts TEXT DEFAULT '[]', notes TEXT,
  active INTEGER DEFAULT 1, created TEXT, updated TEXT
);
CREATE TABLE partner_points (
  id INTEGER PRIMARY KEY, partner_id INTEGER NOT NULL REFERENCES partners(id), name TEXT NOT NULL, types TEXT DEFAULT '[]',
  country TEXT DEFAULT 'RO', county TEXT, city TEXT, address TEXT, postal TEXT, contact TEXT DEFAULT '{}', active INTEGER DEFAULT 1
);
CREATE TABLE authorizations (
  id INTEGER PRIMARY KEY, partner_point_id INTEGER NOT NULL REFERENCES partner_points(id), number TEXT NOT NULL, issuer TEXT,
  versions TEXT DEFAULT '[]', valid_from TEXT, valid_to TEXT, file_id TEXT, file_name TEXT, suspended TEXT
);
CREATE TABLE vehicles (
  id INTEGER PRIMARY KEY, plate TEXT NOT NULL, country TEXT DEFAULT 'RO', type TEXT, carrier_id INTEGER, over35 INTEGER DEFAULT 0,
  capacity INTEGER, docs TEXT DEFAULT '[]', active INTEGER DEFAULT 1
);
CREATE TABLE drivers (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, carrier_id INTEGER, id_type TEXT, id_series TEXT, id_number TEXT, id_expiry TEXT, phone TEXT,
  active INTEGER DEFAULT 1
);
CREATE TABLE categories (
  id INTEGER PRIMARY KEY, parent_id INTEGER, root TEXT, name TEXT NOT NULL, taxable TEXT DEFAULT '{}', sort INTEGER DEFAULT 0, active INTEGER DEFAULT 1
);
CREATE TABLE ewc (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name_ro TEXT, name_en TEXT, hazardous INTEGER DEFAULT 0, active INTEGER DEFAULT 1);
CREATE TABLE articles (
  id INTEGER PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, type TEXT NOT NULL, category_id INTEGER, um TEXT DEFAULT 'kg',
  ewc TEXT DEFAULT '[]', fractions TEXT DEFAULT '[]', active INTEGER DEFAULT 1
);
CREATE TABLE orgs (
  id INTEGER PRIMARY KEY, code TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, partner_id INTEGER, positions TEXT DEFAULT '[]', active INTEGER DEFAULT 1
);
CREATE TABLE org_map (article_id INTEGER NOT NULL, org_id INTEGER NOT NULL, position TEXT, PRIMARY KEY (article_id, org_id));
